let key=new URLSearchParams(location.hash.slice(1)).get('clave')||'';history.replaceState(null,'',location.pathname+location.search);const button=document.querySelector('[data-member-activate]'),status=document.querySelector('[data-member-status]');if(!key){button.hidden=true;status.textContent='Abre el enlace personal que te ha entregado la administración del club.';}button.onclick=async()=>{button.disabled=true;try{const r=await fetch('/api/club/member-access/activate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token:key})});const data=await r.json();if(!r.ok)throw Error(data.error||'No se pudo activar el acceso.');key='';button.hidden=true;status.textContent='Acceso activado para '+data.member.pilot+'. Ya puedes crear tus propios eventos y apuntarte desde el calendario.';}catch(error){status.textContent=error.message;button.disabled=false;}};
